import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"五微","description":"","frontmatter":{"title":"五微","date":"2026-11-17T00:00:00.000Z","seq":5,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/五微.md","filePath":"blogs/声律启蒙·上卷/五微.md"}'),r={name:"blogs/声律启蒙·上卷/五微.md"};function p(l,e,_,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="五微" tabindex="-1">五微 <a class="header-anchor" href="#五微" aria-label="Permalink to &quot;五微&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">来对往，密对稀，燕舞对莺飞。风清对月朗，露重对烟微。霜菊瘦，雨梅肥，客路对渔矶。晚霞舒锦绣，朝露缀珠玑。夏暑客思欹石枕，秋寒妇念寄边衣。春水才深，青草岸边渔父去；夕阳半落，绿莎原上牧童归。</p><p class="poem-stanza">宽对猛，是对非，服美对乘肥。珊瑚对玳瑁，锦绣对珠玑。桃灼灼，柳依依，绿暗对红稀。窗前莺并语，帘外燕双飞。汉致太平三尺剑，周臻大定一戎衣。吟成赏月之诗，只愁月堕；斟满送春之酒，惟憾春归。</p><p class="poem-stanza">声对色，饱对饥，虎节对龙旗。杨花对桂叶，白简对朱衣。尨也吠，燕于飞，荡荡对巍巍。春暄资日气，秋冷借霜威。出使振威冯奉世，治民异等尹翁归。燕我弟兄，载咏棣棠韡韡；命伊将帅，为歌杨柳依依。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
